<div class="page-header mb-4"><div class="row align-items-center"><div class="col"><h2 class="page-title">المستخدمون</h2></div><div class="col-auto"><a class="btn btn-primary" href="/access/users/create"><i class="ti ti-plus ms-2"></i>إضافة مستخدم</a></div></div></div>
<div class="card"><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>المستخدم</th><th>البريد</th><th>الأدوار</th><th>الحالة</th><th></th></tr></thead><tbody><?php foreach($users as $user):?><tr><td><strong><?=e($user['name'])?></strong><div class="text-secondary"><?=e($user['username'])?></div></td><td><?=e($user['email']??'—')?></td><td><?=e($user['role_names']??'—')?></td><td><span class="badge bg-<?= $user['is_active']?'green':'secondary' ?>-lt"><?= $user['is_active']?'نشط':'معطّل' ?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="/access/users/<?=$user['id']?>/edit">تعديل</a> <a class="btn btn-sm btn-outline-secondary" href="/access/users/<?=$user['id']?>/roles">الأدوار</a> <form class="d-inline js-confirm-form" method="post" action="/access/users/<?=$user['id']?>/activate" data-confirm="هل تريد <?= $user['is_active']?'تعطيل':'تفعيل' ?> هذا المستخدم؟"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><input type="hidden" name="active" value="<?=$user['is_active']?'0':'1'?>"><button class="btn btn-sm btn-outline-<?=$user['is_active']?'danger':'success'?>" type="submit"><?=$user['is_active']?'تعطيل':'تفعيل'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div>
